async function main() {
 const root = mkdtempSync(join(tmpdir(), 'issue78-live-fixed-'));
 const store = new KnowledgeStore(root);
 try {
  const strategy = {id:'oversized-strategy', version:'fixture', source:'own', confidence:.25,
   trigger:{question_types:['card_reward'], acts:[1], floor:{min:5,max:18}, deck_cards:[{name:'TEST_CARD',count:{min:1}}]},
   strategy:'格式测试正文，非游戏知识', evidence_status:'conflict', limits:['合成夹具，不能用于游戏'],
   evidence:[{run:'SILENT000001',floor:5,role:'support',ref:'格式证据😀"\\\n'.repeat(1000)},
    {run:'SILENT000002',floor:6,role:'contradict',ref:'反证保持'}]};
  const experience = {id:'oversized-experience',scope:'general:deck',asc:[0,20],lesson:'格式测试结论',status:'active',confidence:'low',
   n_support:1000,n_contradict:1,evidence:Array.from({length:1000},(_,i)=>`SYNTHETIC_${i}`),contradicting:['COUNTEREXAMPLE'],last_seen:'2026-10-26'};
  const reflex = {schema:'reflex-entry-v1',id:'test_reflex',version:1,applies_to:'card_pick',
   predicate:{op:'gte',field:'player.hp',value:10},signal:{kind:'hp',value:1,se:.2,unit:'hp'},label_en:'Test format only',
   evidence:{observations:Array.from({length:1000},(_,i)=>({run_id:`SYNTHETIC_${i}`,floor:8,turn:1})),n_support:1000,n_contradict:2},
   confidence:.5,scope:{character:'silent',ascensions:[0]},source_experience:['TEST_EXPERIENCE']};
  const files = {
   'characters/silent/strategy-entries.json':JSON.stringify({schema:'brain-strategies-v1',character:'silent',entries:[strategy]}),
   'characters/silent/experience.json':JSON.stringify({version:'fixture',entries:[experience]}),
   'characters/silent/reflex.json':JSON.stringify({schema:'reflex-file-v1',character:'silent',entries:[reflex]}),
  };
  store.submit({schema:'knowledge-candidate-v1',id:'fixture',base:null,character:'migration',source:'fixture',files});
  store.validate('fixture'); const version=store.publish('fixture');
  const snapshot=String(store.bind('FIXTURE','fixed-code').snapshot);
  setKnowledgeCharacter('silent');
  const ctx={knowledgeDir:snapshot,logsDir:snapshot,ascension:0,act:1,label:'reward/card',payload:{facts:{act:1,floor:10,deck:'TEST_CARD'}}};
  const host=new ToolHost(buildKnowledgeTools(ctx),ctx);
  const call=async(name,input)=>{
   const result=await host.call(name,input);
   assert(!result.isError,result.text);assert(Buffer.byteLength(result.text)<=24000);
   return JSON.parse(result.text);
  };
  const results=[];
  for(const [tool,input,original] of [
   ['kb_strategies',{query:strategy.id},strategy],['kb_experience',{id:experience.id},experience],['kb_reflex',{query:reflex.id},reflex],
  ]) {
   const projection=await call(tool,input);
   assert.equal(projection.returned,1);assert.equal(projection.oversized_skipped,0);
   assert.equal(projection.knowledge_version,version);
   assert.equal(projection.entries[0].id,original.id);assert.equal(projection.entries[0].confidence,original.confidence);
   if(tool==='kb_strategies') {
    assert.deepEqual(projection.entries[0].trigger,strategy.trigger);
    assert.equal(projection.entries[0].strategy,strategy.strategy);
    assert.equal(projection.entries[0].evidence_status,'conflict');
    assert(projection.entries[0].evidence.some(e=>e.role==='contradict'));
   }
   let offset=0,raw='',digest='',pages=0;
   while(offset!==null) {
    const p=await call(tool,{...input,detail:'full',document_id:original.id,document_offset:offset});
    assert.deepEqual(p.entries,[{id:original.id}]);assert.equal(p.document_offset,offset);
    digest ||= p.document_sha256;assert.equal(p.document_sha256,digest);
    raw+=p.json_fragment;offset=p.next_document_offset;assert(++pages<100);
   }
   assert.equal(createHash('sha256').update(raw).digest('hex'),digest);
   assert.deepEqual(JSON.parse(raw),original);
   results.push({tool,returned:1,pages,bytes:Buffer.byteLength(raw),roundtrip:true});
  }
  for(const facts of [{act:1,floor:25,deck:'TEST_CARD'},{act:1,floor:10,deck:'OTHER_CARD'}]) {
   ctx.payload={facts};
   for(const detail of ['projection','full']) assert.equal((await call('kb_strategies',{query:strategy.id,detail,...(detail==='full'?{document_id:strategy.id}:{})})).returned,0);
  }
  ctx.payload={facts:{act:1,floor:10,deck:'TEST_CARD'}};
  setKnowledgeCharacter('ironclad');
  assert.equal((await call('kb_strategies',{query:strategy.id,detail:'full',document_id:strategy.id})).returned,0);
  assert.deepEqual(store.files(version),files);
  console.log(JSON.stringify({scope:'isolated LIVE synthetic production ToolHost',results,negatives:true,source_files_unchanged:true}));
 } finally {closeIndexedReaders();setKnowledgeCharacter(null);store.close();rmSync(root,{recursive:true,force:true});}
}
main().catch(error=>{console.error(error);process.exitCode=1;});

