   review_observation: { triggers: ['营火', '路线'], conditions: { observable_build_conditions: '原文字条件未求值。' },
    summary: '合成摘要。', rule_candidate: '合成候选。', denominators: { own: { unit: 'runs', n: 3 } },
    counterexamples: [{ label: '合成反证', n: 1 }], limitations: ['合成格式合同。'], status: 'review-only' },
   full_review_evidence: ['中文😀"\\\n'.repeat(8000)],
  };
  const path = 'characters/silent/strategy-entries.json';
  const files = { [path]: JSON.stringify({ schema: 'brain-strategies-v1', character: 'silent', entries: [entry] }) };
  store.submit({ schema: 'knowledge-candidate-v1', id: 'fixture', base: store.current(), character: 'silent', source: 'fixture', files });
  store.validate('fixture'); const version = store.publish('fixture');
  const directory = join(root, 'snapshots', version);
