   const payload = { facts: { act: 1, floor: 3, deck: [] } };
   return { label, payload, toolContext: { label, payload, ascension, knowledgeDir: directory, logsDir: '' },
    knowledge: { mode: 'tools' }, system: 'fixed', options: {}, spec: { label, kind: 'pick', validate: () => [], schema: {} } };
  };
  for (const budget of [2048, 8000, 24000]) {
   const value = attachDecisionKnowledge(request() as any, { enabled: true, bytes: budget }).payload as any;
   assert.equal(value.decision_knowledge.status, 'ok');
   assert.equal(value.decision_knowledge.knowledge_version, version);
   assert.ok(Buffer.byteLength(JSON.stringify(value.decision_knowledge)) <= budget);
   assert.equal(value.decision_knowledge.entries[0].id, entry.id);
   const view=value.decision_knowledge.entries[0];
   assert.equal(view.representation,'compact_decision_view');assert.equal(view.grade,'B+');
   assert.deepEqual(view.trigger,entry.trigger);assert(view.rule.includes(entry.strategy));
   assert(Buffer.byteLength(JSON.stringify(view))<=1900);assert.equal(view.full_document.tool,'kb_strategies');
   assert.equal(view.full_document.input.document_id,entry.id);
  }
  let raw = '', offset: number | null = 0, parts = 0;
  do {
   const result = await decisionContextTool().run({ detail: 'full', source: 'strategy_observation', document_id: entry.id, document_offset: offset }, request().toolContext);
   assert.ok(!result.isError); assert.ok(Buffer.byteLength(result.text) <= 24000);
   const part = JSON.parse(result.text); assert.equal(part.knowledge_version, version);
   raw += part.json_fragment; offset = part.next_document_offset; assert.ok(++parts < 100);
  } while (offset !== null);
  assert.deepEqual(JSON.parse(raw), entry);
  for (const label of ['map/route', 'map/route-plan', 'map/route-review']) {
   assert.deepEqual(questionTypes(label, {}), ['map_route']);
   assert.equal((attachDecisionKnowledge(request(label) as any, { enabled: true, bytes: 8000 }).payload as any).decision_knowledge.entries[0].id, entry.id);
  }
  const off = request(); assert.equal(attachDecisionKnowledge(off as any, { enabled: false, bytes: 8000 }), off);
  assert.deepEqual((attachDecisionKnowledge(request('rest/plan', 9) as any, { enabled: true, bytes: 8000 }).payload as any).decision_knowledge.entries, []);
  setKnowledgeCharacter('ironclad'); const ironclad = request();
  assert.equal(attachDecisionKnowledge(ironclad as any, { enabled: true, bytes: 8000 }), ironclad);
  console.log(JSON.stringify({ scope: 'isolated LIVE synthetic observation contract', budgets: [2048, 8000, 24000], fullParts: parts, exactFullDocument: true, routeLabels: 3, negativeScopes: true, productionWrites: 0 }));
 } finally { closeIndexedReaders(); store.close(); setKnowledgeCharacter(null); rmSync(root, { recursive: true, force: true }); }
}
main().catch(error => { console.error(error); process.exitCode = 1; });

